TAGS = {'travel-planner':'trip vacation holiday journey flight hotel tour','dba':'database sqlite mysql mariadb backup','sql':'sqlite mysql database query','db-schema-designer':'database sqlite mysql table schema','postgres-tuner':'postgresql database slow query','recipe-chef':'cook cooking food meal dinner lunch','fitness-coach':'workout gym exercise training weight','budget-helper':'money saving expenses finance','git-expert':'github commit branch rebase','merge-resolver':'conflict github git','code-reviewer':'review pull request pr diff','bug-hunter':'bug error crash broken fix debug','error-decoder':'error exception message','translator':'translate translation language','resume-writer':'cv job career','interview-coach':'job interview hiring','math-tutor':'maths algebra calculus equation homework','termux-helper':'termux android phone shell','battery-tuner':'phone battery drain slow lag','docker':'container containers compose image','kubernetes':'k8s pod cluster helm','nginx':'web server proxy','prompt-engineer':'prompt llm chatgpt gpt','model-picker':'llm model gguf choose open','quantization-advisor':'gguf quant q4 q8 q2 memory','mcp-builder':'mcp server tool protocol','agent-designer':'agent agents autonomous','storyteller':'story fiction tale novel','poet':'poem poetry verse','summarizer':'summary tldr shorten','proofreader':'grammar spelling typo','email-writer':'mail message reply','marketing-copy':'ad advertising slogan','startup-advisor':'startup founder company idea','security-trainer':'phishing scam awareness','password-policy':'password mfa 2fa login','web-hardening':'csp headers tls https','cli-builder':'command line terminal tool','script-automator':'automate automation script cron','regex-builder':'regex regular expression pattern match'}
def sysprompt(cat, name, focus):
    cname, persona, rules = CATS[cat]
    x = name
    if cat in ('languages',): who = persona.format(x=x); task = f'You help with {focus}'
    elif cat in ('engineering', 'security', 'data', 'product', 'learning', 'orchestrators', 'builder'):
        who = f'{name}'; task = focus if focus.startswith('You') else f'You help with {focus}'
    else:
        who = persona.format(x=x); task = f'You help with {focus}'
    if not task.endswith('.'): task += '.'
    base = f'You are {who}, an AI agent in the "{cname}" team. {task} {rules.format(x=x)}'
    return base + ' If the request is unclear, ask one short question first. If you are not sure, say so instead of guessing. Keep the answer as short as it can be while still complete.'

agents = []; seen = set()
for cat, items in A.items():
    for aid, name, focus in items:
        aid = re.sub(r'[^a-z0-9-]+', '-', aid.lower()).strip('-')
        assert aid not in seen, aid; seen.add(aid)
        agents.append(dict(id=aid, name=name, category=cat, category_name=CATS[cat][0], description=(focus[4:] if focus.startswith('You ') else 'Helps with ' + focus).rstrip('.'), tags=TAGS.get(aid, ''), system=sysprompt(cat, name, focus)))
out = dict(version=1, count=len(agents), categories={k: v[0] for k, v in CATS.items()}, agents=agents)
json.dump(out, open(os.path.join(ROOT, 'mcp', 'agents.json'), 'w'), indent=0, ensure_ascii=False)
print(len(agents), 'agents;', {k: len(v) for k, v in A.items()})
